package cli

import (
	"fmt"
	"io"
	"strings"
	"text/tabwriter"
)

// Settings of the tabwriter that WriteTable uses.
const (
	tableMinWidth = 0
	tableTabWidth = 8
	tablePadding  = 2
)

// WriteTable writes header and rows as columns aligned with spaces.
// Commands use it for every text output that lists several items.
func WriteTable(w io.Writer, header []string, rows [][]string) error {
	tw := tabwriter.NewWriter(w, tableMinWidth, tableTabWidth, tablePadding, ' ', 0)
	_, err := io.WriteString(tw, strings.Join(header, "\t")+"\n")
	if err != nil {
		return err
	}
	for _, row := range rows {
		_, err = io.WriteString(tw, strings.Join(row, "\t")+"\n")
		if err != nil {
			return err
		}
	}
	err = tw.Flush()
	if err != nil {
		return fmt.Errorf("flush table: %w", err)
	}
	return nil
}

// StatusText returns the word shown for the status of an item.
func StatusText(done bool) string {
	if done {
		return "done"
	}
	return "open"
}

package taskcmd

import (
	"time"

	"example.com/go-cli/internal/cli"
	"example.com/go-cli/internal/domain/task"
)

// taskView is how one task appears in the output of the task commands.
type taskView struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Done      bool      `json:"done"`
	CreatedAt time.Time `json:"created_at"`
}

// toTaskView converts Task to taskView.
func toTaskView(t task.Task) taskView {
	return taskView{ID: t.ID, Title: t.Title, Done: t.Done, CreatedAt: t.CreatedAt}
}

// status returns the text shown in the STATUS column.
func (v taskView) status() string {
	return cli.StatusText(v.Done)
}

package taskcmd

import (
