)

// addOptions holds the arguments and flags of task add.
type addOptions struct {
	title string
}

// addOutput is the result of task add.
type addOutput struct {
	Task taskView `json:"task"`
}

// newAdd returns the task add command.
func newAdd(svc *task.Service) *cli.Command {
	var opts addOptions
	return &cli.Command{
		Name:    "add",
		Summary: "Add a task",
		Args:    []cli.Arg{{Name: "title", Value: &opts.title}},
		Run: func(ctx context.Context) (cli.Output, error) {
			return runAdd(ctx, svc, opts)
		},
	}
}

// runAdd runs task add.
func runAdd(ctx context.Context, svc *task.Service, opts addOptions) (addOutput, error) {
	if strings.TrimSpace(opts.title) == "" {
		return addOutput{}, fmt.Errorf("%w: title must be 1 to 100 characters", errkind.ErrInvalid)
	}
	added, err := svc.Add(ctx, opts.title)
	if err != nil {
		return addOutput{}, err
	}
	return addOutput{Task: toTaskView(added)}, nil
}

// WriteText implements cli.Output.
func (o addOutput) WriteText(w io.Writer) error {
	_, err := fmt.Fprintf(w, "Added task %d: %s\n", o.Task.ID, o.Task.Title)
	return err
}

package task

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"time"

	"example.com/go-cli/internal/errkind"
)

// Service runs the task use cases.
type Service struct {
	repo Repository
	now  func() time.Time
}

// NewService returns a Service that keeps tasks in repo and reads the current time from now.
func NewService(repo Repository, now func() time.Time) *Service {
	return &Service{repo: repo, now: now}
}

// Add creates an open task with the given title.
func (s *Service) Add(ctx context.Context, title string) (Task, error) {
	trimmed := strings.TrimSpace(title)
	err := validateTitle(trimmed)
	if err != nil {
		return Task{}, err
	}
	tasks, err := s.repo.Load(ctx)
	if err != nil {
		return Task{}, err
	}
	created := Task{ID: nextID(tasks), Title: trimmed, CreatedAt: s.now().UTC().Truncate(time.Second)}
	err = s.repo.Save(ctx, append(tasks, created))
	if err != nil {
		return Task{}, err
	}
	return created, nil
}

// Complete marks the task with the given ID as done.
// Completing a done task changes nothing.
func (s *Service) Complete(ctx context.Context, id int) (Task, error) {
	tasks, err := s.repo.Load(ctx)
	if err != nil {
		return Task{}, err
	}
	i, err := indexOf(tasks, id)
	if err != nil {
		return Task{}, err
	}
	tasks[i].Done = true
	err = s.repo.Save(ctx, tasks)
	if err != nil {
		return Task{}, err
	}
	return tasks[i], nil
}

// List returns the tasks that match filter in ID order.
func (s *Service) List(ctx context.Context, filter Filter) ([]Task, error) {
	tasks, err := s.repo.Load(ctx)
	if err != nil {
		return nil, err
	}
	matched := make([]Task, 0, len(tasks))
	for _, t := range tasks {
		if t.Done && !filter.IncludeDone {
			continue
		}
		matched = append(matched, t)
	}
	return matched, nil
}

// Rename changes the title of the task with the given ID.
func (s *Service) Rename(ctx context.Context, title string, id int) (Task, error) {
	trimmed := strings.TrimSpace(title)
	err := validateTitle(trimmed)
	if err != nil {
		return Task{}, err
	}
	tasks, err := s.repo.Load(ctx)
	if err != nil {
		return Task{}, err
	}
	i, err := indexOf(tasks, id)
	if err != nil {
		return Task{}, err
	}
	tasks[i].Title = trimmed
	err = s.repo.Save(ctx, tasks)
	if err != nil {
		return Task{}, err
	}
	return tasks[i], nil
}

// indexOf returns the position of the task with the given ID in tasks.
func indexOf(tasks []Task, id int) (int, error) {
	i := slices.IndexFunc(tasks, func(t Task) bool { return t.ID == id })
	if i < 0 {
		return 0, fmt.Errorf("%w: task %d", errkind.ErrNotFound, id)
	}
	return i, nil
}

// nextID returns the ID for a new task, one more than the largest ID in tasks.
func nextID(tasks []Task) int {
	maxID := 0
	for _, t := range tasks {
		maxID = max(maxID, t.ID)
	}
	return maxID + 1
}

// Package app builds the go-cli command tree and connects it to the process environment.
//
// It is the only package that knows every other package: it reads the configuration, creates the adapters and services, and registers every command group.
package app

import (
	"context"
	"io"
	"path/filepath"
	"runtime/debug"
	"time"

	"example.com/go-cli/internal/adapter/taskstore"
	"example.com/go-cli/internal/cli"
	"example.com/go-cli/internal/command/taskcmd"
	"example.com/go-cli/internal/domain/task"
)

// Env is the process environment the CLI runs in.
// main passes the real one and tests pass fakes.
type Env struct {
	Stdout io.Writer
	Stderr io.Writer
	Getenv func(key string) string
	Now    func() time.Time
}

// name is the name of the CLI.
const name = "go-cli"

// New builds the command tree.
// It does not read or write any file.
func New(env Env) (*cli.App, error) {
	cfg, err := loadConfig(env.Getenv)
	if err != nil {
		return nil, err
	}
	tasks := task.NewService(taskstore.New(filepath.Join(cfg.dataDir, "task-data.json")), env.Now)
	return &cli.App{
		Name:    name,
		Version: version(),
		Groups: []*cli.Group{
			taskcmd.New(tasks),
		},
	}, nil
}

// Run builds the command tree, runs it with args (without the program name) and returns the exit code.
func Run(ctx context.Context, args []string, env Env) int {
	streams := cli.IO{Out: env.Stdout, Err: env.Stderr}
	a, err := New(env)
	if err != nil {
		return cli.Fail(streams, name, err)
	}
	return a.Run(ctx, args, streams)
}

// version returns the module version that go install recorded, or "(devel)" for a local build.
func version() string {
	info, ok := debug.ReadBuildInfo()
	if !ok || info.Main.Version == "" {
		return "(devel)"
	}
	return info.Main.Version
}

package taskcmd

import (
	"context"
	"fmt"
	"io"

	"example.com/go-cli/internal/cli"
	"example.com/go-cli/internal/domain/task"
)

// completeOptions holds the arguments and flags of task complete.
type completeOptions struct {
	id string
}

// completeOutput is the result of task complete.
type completeOutput struct {
	Task taskView `json:"task"`
}

// newComplete returns the task complete command.
func newComplete(svc *task.Service) *cli.Command {
	var opts completeOptions
	return &cli.Command{
		Name:    "complete",
		Summary: "Mark a task as done",
		Args:    []cli.Arg{{Name: "id", Value: &opts.id}},
		Run: func(ctx context.Context) (cli.Output, error) {
			return runComplete(ctx, svc, opts)
		},
	}
}

// runComplete runs task complete.
func runComplete(ctx context.Context, svc *task.Service, opts completeOptions) (completeOutput, error) {
	id, err := task.ParseID(opts.id)
	if err != nil {
		return completeOutput{}, err
	}
	completed, err := svc.Complete(ctx, id)
	if err != nil {
		return completeOutput{}, err
	}
	return completeOutput{Task: toTaskView(completed)}, nil
}

// WriteText implements cli.Output.
func (o completeOutput) WriteText(w io.Writer) error {
	_, err := fmt.Fprintf(w, "Task %d completed: %s\n", o.Task.ID, o.Task.Title)
	return err
}

package taskcmd_test

import (
	"testing"

	"example.com/go-cli/internal/app/apptest"
)

func TestComplete(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name  string
		setup [][]string
		args  []string
		want  apptest.Result
	}{
		{
			name:  "completes_a_task",
			setup: [][]string{{"task", "add", "Buy milk"}},
			args:  []string{"task", "complete", "1"},
			want:  apptest.Result{Code: 0, Stdout: "Task 1 completed: Buy milk\n"},
		},
		{
			name:  "keeps_a_done_task_done",
			setup: [][]string{{"task", "add", "Buy milk"}, {"task", "complete", "1"}},
			args:  []string{"task", "complete", "1"},
			want:  apptest.Result{Code: 0, Stdout: "Task 1 completed: Buy milk\n"},
		},
		{
			name:  "writes_json",
			setup: [][]string{{"task", "add", "Buy milk"}},
			args:  []string{"task", "complete", "1", "--json"},
			want: apptest.Result{Code: 0, Stdout: `{
  "task": {
    "id": 1,
    "title": "Buy milk",
    "done": true,
    "created_at": "2026-01-02T03:04:05Z"
  }
}
`},
		},
		{
			name: "rejects_an_id_that_is_not_a_number",
			args: []string{"task", "complete", "one"},
			want: apptest.Result{
				Code: 2,
				Stderr: "go-cli: invalid input: task ID must be a positive integer: \"one\"\n" +
					"Run 'go-cli task complete --help' for usage.\n",
			},
		},
		{
			name:  "reports_a_missing_task",
			setup: [][]string{{"task", "add", "Buy milk"}},
			args:  []string{"task", "complete", "2"},
			want:  apptest.Result{Code: 3, Stderr: "go-cli: not found: task 2\n"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			h := apptest.New(t)
			for _, args := range tt.setup {
				h.Setup(args...)
			}
			got := h.Run(tt.args...)
			if got != tt.want {
				t.Errorf("Run(%q) = %+v, want %+v", tt.args, got, tt.want)
			}
		})
	}
}

