func TestParseID(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name    string
		s       string
		want    int
		wantErr error
	}{
		{name: "accepts_a_positive_integer", s: "12", want: 12, wantErr: nil},
		{name: "rejects_zero", s: "0", want: 0, wantErr: errkind.ErrInvalid},
