		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got, err := task.ParseID(tt.s)
			if got != tt.want || !errors.Is(err, tt.wantErr) {
				t.Errorf("ParseID(%q) = %d, %v, want %d, %v", tt.s, got, err, tt.want, tt.wantErr)
			}
		})
	}
}

// Package errkind defines the kinds of errors that decide the exit code of the CLI.
//
// Other packages wrap one of these errors with fmt.Errorf("%w: detail", errkind.ErrX).
package errkind

import "errors"

var (
	// ErrInvalid reports input that breaks a rule.
	// The CLI exits with code 2.
	ErrInvalid = errors.New("invalid input")
	// ErrNotFound reports that the requested item does not exist.
	// The CLI exits with code 3.
	ErrNotFound = errors.New("not found")
	// ErrConflict reports that the change conflicts with the saved data.
	// The CLI exits with code 4.
	ErrConflict = errors.New("conflict")
)

package taskcmd

import (
	"context"
	"flag"
	"io"
	"strconv"

	"example.com/go-cli/internal/cli"
	"example.com/go-cli/internal/domain/task"
)

// listOptions holds the arguments and flags of task list.
type listOptions struct {
	includeDone bool
}

// listOutput is the result of task list.
type listOutput struct {
	Tasks []taskView `json:"tasks"`
}

// newList returns the task list command.
func newList(svc *task.Service) *cli.Command {
	var opts listOptions
	return &cli.Command{
		Name:    "list",
		Summary: "List open tasks",
		Flags: func(fs *flag.FlagSet) {
			fs.BoolVar(&opts.includeDone, "include-done", false, "Include completed tasks")
		},
		Run: func(ctx context.Context) (cli.Output, error) {
			return runList(ctx, svc, opts)
		},
	}
}

// runList runs task list.
func runList(ctx context.Context, svc *task.Service, opts listOptions) (listOutput, error) {
	tasks, err := svc.List(ctx, task.Filter{IncludeDone: opts.includeDone})
	if err != nil {
		return listOutput{}, err
	}
	views := make([]taskView, 0, len(tasks))
	for _, t := range tasks {
		views = append(views, toTaskView(t))
	}
	return listOutput{Tasks: views}, nil
}

// WriteText implements cli.Output.
func (o listOutput) WriteText(w io.Writer) error {
	rows := make([][]string, 0, len(o.Tasks))
	for _, v := range o.Tasks {
		rows = append(rows, []string{strconv.Itoa(v.ID), v.status(), v.Title})
	}
	return cli.WriteTable(w, []string{"ID", "STATUS", "TITLE"}, rows)
}

